/* Generated by `helix system machines` from machine.ts beside it. Do not
   edit: change the machine and run it again. */
import { type TypeaheadContext, type TypeaheadInput, chooses, clear, moves, search, searching, takes } from './machine.js'

export type { TypeaheadContext, TypeaheadInput } from './machine.js'

/** The name machine.ts exports the machine as. */
export const NAME = 'typeahead'

/** The state `idle`. */
export const STATE_IDLE = 0
/** The state `searching`. */
export const STATE_SEARCHING = 1
/** Each state's name, by its number. */
export const STATES = ['idle', 'searching'] as const

/** Each state as the machine writes it, by the number a deadline names its owner by. */
export const NODES = ['idle', 'searching'] as const

/** The event `TYPE`. */
export const EVENT_TYPE = 0
/** The event `RESET`. */
export const EVENT_RESET = 1
/** Each event's name, by its number. */
export const EVENTS = ['TYPE', 'RESET'] as const

/** The effect `focus`. */
export const EFFECT_FOCUS = 0
/** The effect `select`. */
export const EFFECT_SELECT = 1
/** The effect `deadline`. */
export const EFFECT_DEADLINE = 2
/** The effect `deadline-end`. */
export const EFFECT_DEADLINE_END = 3
/** Each effect's name, by its number. */
export const EFFECTS = ['focus', 'select', 'deadline', 'deadline-end'] as const

/** Each request event's name, by its number. */
export const ASKS = [] as const

/** A literal an effect is given. */
export type Argument = Readonly<Record<string, boolean | number | string>>

/** An effect the host performs: its number, and its argument where it has one. */
export type Effect = readonly [effect: number, argument?: Argument]

/** A move: the state it leaves the machine in, the context after it, and the effects it runs, in order. */
export interface Move {
  readonly context: TypeaheadContext
  readonly effects: readonly Effect[]
  readonly state: number
}

/** A request: the events the host asks with first, in order, and the move for each outcome. */
export interface Asking {
  readonly accept: Move
  readonly ask: readonly number[]
  readonly refuse: Move
}

/** The state the machine is in, read from its context. */
export const start = (context: TypeaheadContext): number =>
  searching(context) ? STATE_SEARCHING : STATE_IDLE

/** The effects of starting in a state, as a host that mounts the machine runs them. */
export const entering = (state: number): readonly Effect[] => {
  switch (state) {
    case STATE_SEARCHING:
      return [[EFFECT_DEADLINE, { ms: 500, owner: 1 }]]
  }
  return []
}

/** What `idle` does with each event. */
const inIdle = (context: TypeaheadContext, event: number, input: TypeaheadInput): Move | Asking | undefined => {
  switch (event) {
    case EVENT_TYPE:
      return chooses(context, input) ? { context: search(context, input), effects: [[EFFECT_FOCUS], [EFFECT_SELECT], [EFFECT_DEADLINE, { ms: 500, owner: 1 }]], state: STATE_SEARCHING } : moves(context, input) ? { context: search(context, input), effects: [[EFFECT_FOCUS], [EFFECT_DEADLINE, { ms: 500, owner: 1 }]], state: STATE_SEARCHING } : takes(context, input) ? { context: search(context, input), effects: [[EFFECT_DEADLINE, { ms: 500, owner: 1 }]], state: STATE_SEARCHING } : undefined
  }
  return undefined
}

/** What `searching` does with each event. */
const inSearching = (context: TypeaheadContext, event: number, input: TypeaheadInput): Move | Asking | undefined => {
  switch (event) {
    case EVENT_TYPE:
      return chooses(context, input) ? { context: search(context, input), effects: [[EFFECT_DEADLINE_END, { owner: 1 }], [EFFECT_FOCUS], [EFFECT_SELECT], [EFFECT_DEADLINE, { ms: 500, owner: 1 }]], state: STATE_SEARCHING } : moves(context, input) ? { context: search(context, input), effects: [[EFFECT_DEADLINE_END, { owner: 1 }], [EFFECT_FOCUS], [EFFECT_DEADLINE, { ms: 500, owner: 1 }]], state: STATE_SEARCHING } : takes(context, input) ? { context: search(context, input), effects: [[EFFECT_DEADLINE_END, { owner: 1 }], [EFFECT_DEADLINE, { ms: 500, owner: 1 }]], state: STATE_SEARCHING } : undefined
    case EVENT_RESET:
      return { context: clear(context), effects: [[EFFECT_DEADLINE_END, { owner: 1 }]], state: STATE_IDLE }
  }
  return undefined
}

/**
 * What an event does in a state: a move, a request, or `undefined` where the
 * state ignores it.
 */
export const step = (state: number, context: TypeaheadContext, event: number, input: TypeaheadInput): Move | Asking | undefined => {
  switch (state) {
    case STATE_IDLE:
      return inIdle(context, event, input)
    case STATE_SEARCHING:
      return inSearching(context, event, input)
  }
  return undefined
}

/**
 * The move a state's deadline makes when it ends, or `undefined` where the
 * state `owner` names is not active in `state`.
 */
export const expire = (state: number, context: TypeaheadContext, owner: number): Move | undefined => {
  switch (state) {
    case STATE_SEARCHING:
      return owner === 1 ? { context: clear(context), effects: [[EFFECT_DEADLINE_END, { owner: 1 }]], state: STATE_IDLE } : undefined
  }
  return undefined
}

/** The move the machine's cancel makes from a state, where it has one. */
export const cancel = (_state: number, _context: TypeaheadContext): Move | undefined => undefined

/** The custom states a host records while the machine is in `state`. */
export const mark = (_state: number): readonly string[] => []
